import {
  ArrowLeft, ArrowRight, BookOpen, CalendarDays, Check, ChevronDown, ClipboardCheck,
  Clock3, FileText, HeartHandshake, Home, LogOut, Menu, Moon, Plus,
  QrCode, Search, Settings2, Sparkles, Target, Trash2, Users, X, Zap,
} from 'lucide-react';
import { Link, Route, Switch, useLocation, useParams, Router as WouterRouter } from 'wouter';
import {
  getGetAttendanceQueryKey, getGetBibleStudyQueryKey, getGetCurrentUserQueryKey,
  getHealthCheckQueryKey,
  getGetServantDashboardQueryKey, getGetStudentDashboardQueryKey, getGetStudentProfileQueryKey,
  getListBibleReadingsQueryKey, getListBibleStudiesQueryKey, getListClassStudentsQueryKey,
  getListEventsQueryKey, getListSpiritualRecordsQueryKey, useCheckInStudent, useCreateBibleReading,
  useCreateBibleStudy, useCreateSpiritualRecord, useDeleteBibleReading, useGetAttendance,
  useGetBibleStudy, useGetCurrentUser, useGetServantDashboard, useGetStudentDashboard,
  useGetStudentProfile, useHealthCheck, useListBibleReadings, useListBibleStudies, useListClassStudents,
  useListEvents, useListSpiritualRecords, useLogin, useLogout, useSignup, useSubmitBibleStudy,
  useUpdateBibleReading,
} from '@workspace/api-client-react';
