import NotFound from '@/pages/not-found';
import './index.css';

const queryClient = new QueryClient();

const cn = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(' ');
const fmtDate = (value?: string | null) => value ? new Intl.DateTimeFormat('ar-EG', { day: 'numeric', month: 'short' }).format(new Date(value)) : '—';
const fmtLongDate = (value?: string | null) => value ? new Intl.DateTimeFormat('ar-EG', { weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(value)) : '—';
const initials = (name = '') => name.split(' ').filter(Boolean).slice(0, 2).map((part) => part[0]).join('');

function Button({ children, className = '', variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'outline' | 'danger' }) {
  return <button className={cn('inline-flex min-h-11 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold transition-transform duration-200 active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-45', variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-105', variant === 'ghost' && 'text-muted-foreground hover:bg-secondary hover:text-foreground', variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/60', variant === 'danger' && 'border border-accent/30 bg-accent/10 text-accent hover:bg-accent/20', className)} {...props}>{children}</button>;
}

function Input({ className = '', ...props }: React.InputHTMLAttributes<HTMLInputElement>) {
  return <input className={cn('h-12 w-full rounded-xl border border-input bg-background/70 px-4 text-sm text-foreground outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} {...props} />;
}

function Select({ className = '', ...props }: React.SelectHTMLAttributes<HTMLSelectElement>) {
  return <select className={cn('h-12 w-full appearance-none rounded-xl border border-input bg-background/70 px-4 text-sm text-foreground outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15', className)} {...props} />;
}

function Label({ children }: { children: React.ReactNode }) {
  return <label className="mb-2 block text-xs font-bold text-muted-foreground">{children}</label>;
}

function Avatar({ name, size = 'md' }: { name?: string; size?: 'sm' | 'md' | 'lg' }) {
  return <div className={cn('flex shrink-0 items-center justify-center rounded-full border border-primary/25 bg-primary/10 font-bold text-primary', size === 'sm' && 'h-8 w-8 text-[10px]', size === 'md' && 'h-10 w-10 text-xs', size === 'lg' && 'h-16 w-16 text-lg')} data-testid={`avatar-${name || 'user'}`}>{initials(name)}</div>;
}

function LoadingScreen() {
  return <div className="thanwy-grid flex min-h-[100dvh] items-center justify-center bg-background"><div className="flex flex-col items-center gap-5"><ThanwyLogo compact /><div className="flex gap-1.5"><i className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary" /><i className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary [animation-delay:150ms]" /><i className="h-1.5 w-1.5 animate-pulse rounded-full bg-primary [animation-delay:300ms]" /></div><p className="text-sm text-muted-foreground">نجهز مساحتك الروحية...</p></div></div>;
}

function QueryError({ onRetry }: { onRetry?: () => void }) {
  return <div className="rounded-2xl border border-accent/25 bg-accent/5 p-8 text-center" data-testid="state-error"><div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent/10 text-accent"><X size={22} /></div><h3 className="font-bold">حدث عطل بسيط</h3><p className="mt-2 text-sm text-muted-foreground">لم نتمكن من تحميل هذه البيانات. حاول مرة أخرى.</p>{onRetry && <Button onClick={onRetry} variant="outline" className="mt-5">إعادة المحاولة</Button>}</div>;
}

function EmptyState({ icon: Icon = Sparkles, title, body }: { icon?: typeof Sparkles; title: string; body: string }) {
  return <div className="rounded-2xl border border-dashed border-border bg-card/40 p-8 text-center" data-testid="state-empty"><Icon className="mx-auto mb-3 text-primary" size={25} /><h3 className="font-bold">{title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{body}</p></div>;
}

function Metric({ label, value, detail, color = 'primary', icon: Icon }: { label: string; value: string | number; detail?: string; color?: 'primary' | 'accent'; icon: typeof Target }) {
  return <div className="rounded-2xl border border-border bg-card p-5" data-testid={`metric-${label}`}><div className="mb-5 flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span><span className={cn('flex h-9 w-9 items-center justify-center rounded-xl', color === 'primary' ? 'bg-primary/10 text-primary' : 'bg-accent/10 text-accent')}><Icon size={17} /></span></div><div className="text-3xl font-extrabold tracking-tight">{value}</div>{detail && <div className="mt-1 text-xs text-muted-foreground">{detail}</div>}</div>;
}

function SectionHeader({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div>{eyebrow && <div className="mb-1 text-[10px] font-bold uppercase tracking-[.2em] text-primary">{eyebrow}</div>}<h2 className="text-lg font-extrabold">{title}</h2></div>{action}</div>;
}

const studentNav = [
  { href: '/', label: 'الرئيسية', icon: Home },
  { href: '/student/spiritual', label: 'حياتي الروحية', icon: HeartHandshake },
  { href: '/student/bible', label: 'قراءة الكتاب', icon: BookOpen },
  { href: '/student/attendance', label: 'الحضور', icon: ClipboardCheck },
  { href: '/student/studies', label: 'الدراسات', icon: FileText },
];
const servantNav = [
  { href: '/', label: 'الرئيسية', icon: Home },
  { href: '/servant/attendance', label: 'الحضور', icon: ClipboardCheck },
  { href: '/servant/spiritual', label: 'المتابعة الروحية', icon: HeartHandshake },
  { href: '/servant/readings', label: 'القراءات', icon: BookOpen },
  { href: '/servant/studies', label: 'الدراسات', icon: FileText },
];

function AppShell({ user, children }: { user: AuthUser; children: React.ReactNode }) {
  const [mobileMenu, setMobileMenu] = useState(false);
  const [location, setLocation] = useLocation();
  const logout = useLogout();
  const nav = user.role === 'SERVANT' ? servantNav : studentNav;
  const doLogout = () => logout.mutate(undefined, { onSuccess: () => setLocation('/login') });
  return <div className="thanwy-noise min-h-[100dvh] bg-background" dir="rtl">
    <aside className={cn('fixed inset-y-0 right-0 z-40 flex w-[270px] flex-col border-l border-sidebar-border bg-sidebar px-5 py-6 transition-transform duration-300 lg:translate-x-0', mobileMenu ? 'translate-x-0' : 'translate-x-full')} data-testid="sidebar">
      <ThanwyLogo className="mb-12" />
      <div className="mb-4 px-3 text-[10px] font-bold uppercase tracking-[.2em] text-muted-foreground">مساحتك</div>
      <nav className="space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setMobileMenu(false)} className={cn('flex min-h-12 items-center gap-3 rounded-xl px-3 text-sm font-semibold transition', location === href ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-sidebar-accent hover:text-foreground')} data-testid={`link-nav-${label}`}><Icon size={18} /><span>{label}</span>{href === '/' && user.role === 'SERVANT' && <span className="mr-auto h-1.5 w-1.5 rounded-full bg-accent" />}</Link>)}</nav>
      <div className="mt-auto space-y-2 border-t border-sidebar-border pt-5">
        <div className="flex items-center gap-3 rounded-xl bg-sidebar-accent/60 p-3"><Avatar name={user.name} size="sm" /><div className="min-w-0"><div className="truncate text-sm font-bold">{user.name}</div><div className="truncate text-[10px] text-muted-foreground">{user.className || 'عضو ثانوي'}</div></div></div>
        <button onClick={doLogout} className="flex min-h-11 w-full items-center gap-3 rounded-xl px-3 text-sm font-semibold text-muted-foreground hover:bg-accent/10 hover:text-accent" data-testid="button-logout"><LogOut size={17} />تسجيل الخروج</button>
      </div>
    </aside>
    {mobileMenu && <button aria-label="إغلاق القائمة" onClick={() => setMobileMenu(false)} className="fixed inset-0 z-30 bg-background/70 backdrop-blur-sm lg:hidden" data-testid="button-close-menu" />}
    <main className="min-h-[100dvh] lg:mr-[270px]">
      <header className="sticky top-0 z-20 flex h-[76px] items-center justify-between border-b border-border bg-background/85 px-5 backdrop-blur-xl sm:px-8 lg:px-10"><div className="lg:hidden"><button onClick={() => setMobileMenu(true)} className="flex h-11 w-11 items-center justify-center rounded-xl bg-card text-foreground" data-testid="button-open-menu"><Menu size={20} /></button></div><div className="hidden lg:block"><div className="text-xs text-muted-foreground">الأحد، ٢٣ فبراير ٢٠٢٥</div><div className="mt-1 text-sm font-bold">{user.role === 'SERVANT' ? 'صباح الخدمة يا ' : 'أهلاً بك يا '}{user.name.split(' ')[0]}</div></div><div className="flex items-center gap-3"><div className="hidden rounded-xl border border-primary/20 bg-primary/5 px-3 py-2 text-xs font-semibold text-primary sm:block"><span className="ml-2 inline-block h-1.5 w-1.5 rounded-full bg-primary" />أسبوع النمو ٠٧</div><Avatar name={user.name} /></div></header>
      <div className="page-enter mx-auto max-w-[1420px] px-5 py-7 pb-28 sm:px-8 lg:px-10 lg:py-10">{children}</div>
    </main>
    <nav className="fixed inset-x-4 bottom-4 z-20 flex items-center justify-around rounded-2xl border border-border bg-sidebar/95 p-2 shadow-xl backdrop-blur-xl lg:hidden">{nav.slice(0, 4).map(({ href, label, icon: Icon }) => <Link key={href} href={href} className={cn('flex min-h-12 min-w-14 flex-col items-center justify-center gap-1 rounded-xl text-[10px] font-bold', location === href ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')} data-testid={`mobile-nav-${label}`}><Icon size={17} /><span>{label}</span></Link>)}</nav>
  </div>;
}

function Protected({ children }: { children: React.ReactNode }) {
  const { data: user, isLoading, isError, refetch } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  if (isLoading) return <LoadingScreen />;
  if (isError || !user) return <div className="flex min-h-[100dvh] items-center justify-center bg-background p-6"><div className="max-w-sm text-center"><ThanwyLogo className="mx-auto mb-7" /><h1 className="text-2xl font-extrabold">هذه المساحة لأعضاء ثانوي</h1><p className="mt-3 text-sm leading-7 text-muted-foreground">سجّل دخولك لتتابع رحلتك وتبقى قريباً من مجتمعك.</p><div className="mt-6 flex justify-center gap-3"><Link href="/login" className="inline-flex min-h-11 items-center rounded-xl bg-primary px-5 text-sm font-bold text-primary-foreground" data-testid="link-login-required">تسجيل الدخول</Link><Button variant="ghost" onClick={() => refetch()}>إعادة المحاولة</Button></div></div></div>;
  return <AppShell user={user}>{children}</AppShell>;
}

function Landing() {
  const { data: health } = useHealthCheck({ query: { queryKey: getHealthCheckQueryKey(), retry: false } });
  const { data: user, isLoading } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey(), retry: false } });
  if (isLoading) return <LoadingScreen />;
  if (user) return <Protected>{user.role === 'SERVANT' ? <ServantDashboard /> : <StudentDashboard />}</Protected>;
  return <div className="thanwy-grid relative min-h-[100dvh] overflow-hidden bg-background px-5 py-7 sm:px-10 lg:px-16">
    <div className="absolute -right-28 top-16 h-72 w-72 rounded-full bg-primary/10 blur-3xl" /><div className="absolute -left-40 bottom-0 h-96 w-96 rounded-full bg-accent/5 blur-3xl" />
    <header className="relative flex items-center justify-between"><ThanwyLogo /><div className="flex items-center gap-3"><span className="hidden text-[10px] font-bold text-muted-foreground sm:block">{health?.status === 'ok' ? 'المجتمع متصل' : 'مساحة هادئة للمتابعة'}</span><Link href="/login" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-card/80 px-4 text-sm font-bold" data-testid="link-landing-login">تسجيل الدخول <ArrowLeft size={16} /></Link></div></header>
    <section className="relative mx-auto grid max-w-6xl items-center gap-14 py-20 lg:grid-cols-[1.1fr_.9fr] lg:py-28"><div><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/25 bg-primary/5 px-3 py-2 text-xs font-bold text-primary"><Sparkles size={14} /> رفيقك في رحلة النمو</div><h1 className="max-w-2xl text-5xl font-extrabold leading-[1.08] tracking-[-.04em] sm:text-7xl">كل أحد،<br /><span className="text-primary">خطوة أقرب.</span></h1><p className="mt-7 max-w-lg text-base leading-8 text-muted-foreground sm:text-lg">ثانوي يجمع ما يهمك في مكان واحد: صلاتك، قراءتك، حضورك ومجتمعك. مساحة هادئة تساعدك أن ترى الطريق وتكمل.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/signup" className="inline-flex min-h-12 items-center gap-2 rounded-xl bg-primary px-5 text-sm font-extrabold text-primary-foreground" data-testid="link-landing-signup">ابدأ رحلتك <ArrowLeft size={17} /></Link><Link href="/login" className="inline-flex min-h-12 items-center rounded-xl border border-border bg-card px-5 text-sm font-bold" data-testid="link-landing-login-secondary">لدي حساب بالفعل</Link></div></div><div className="relative"><div className="rounded-[2rem] border border-primary/20 bg-card/80 p-4 shadow-2xl shadow-primary/5 backdrop-blur"><div className="rounded-[1.4rem] bg-secondary/55 p-6"><div className="mb-7 flex items-center justify-between"><span className="text-xs font-bold text-muted-foreground">ملخص هذا الأسبوع</span><span className="text-[10px] text-primary">الأسبوع ٠٧</span></div><div className="flex items-end gap-5"><div className="flex h-40 w-40 items-center justify-center rounded-full" style={{ background: 'conic-gradient(hsl(var(--primary)) 78%, hsl(var(--muted)) 0)' }}><div className="flex h-32 w-32 flex-col items-center justify-center rounded-full bg-card"><span className="text-4xl font-extrabold">٧٨<span className="text-base">٪</span></span><span className="text-[10px] text-muted-foreground">تقدمك</span></div></div><div className="space-y-4 pb-2 text-xs"><div><div className="mb-1 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-primary" />الصلاة اليومية</div><b className="text-lg">٢٤ / ٢٨</b></div><div><div className="mb-1 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-accent" />قراءة الإنجيل</div><b className="text-lg">٥ أيام</b></div></div></div></div></div><div className="absolute -bottom-6 -left-5 rounded-2xl border border-border bg-sidebar p-4 shadow-xl sm:-left-10"><div className="mb-2 text-[10px] text-muted-foreground">اللقاء القادم</div><div className="flex items-center gap-3"><div className="rounded-xl bg-accent/10 p-2 text-accent"><CalendarDays size={18} /></div><div><div className="text-sm font-bold">اجتماع الأحد</div><div className="mt-1 text-[10px] text-muted-foreground">بعد ٣ أيام · ٧:٠٠ م</div></div></div></div></div></section>
    <div className="relative mx-auto grid max-w-6xl grid-cols-1 gap-3 border-t border-border pt-8 text-sm text-muted-foreground sm:grid-cols-3"><div className="flex items-center gap-3"><Target className="text-primary" size={18} /> تابع عاداتك بصدق</div><div className="flex items-center gap-3"><Users className="text-primary" size={18} /> ابق قريباً من فصلك</div><div className="flex items-center gap-3"><BookOpen className="text-primary" size={18} /> اقرأ كلمة كل يوم</div></div>
  </div>;
}

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-9 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.22em] text-primary">{eyebrow}</div><h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">{title}</h1>{description && <p className="mt-3 max-w-2xl text-sm leading-7 text-muted-foreground">{description}</p>}</div>{action}</div>;
}

function EventRow({ event }: { event: Event }) {
  return <div className="flex items-center gap-3 border-b border-border/70 py-4 last:border-0" data-testid={`event-${event.id}`}><div className="flex h-11 w-11 shrink-0 flex-col items-center justify-center rounded-xl bg-primary/10 text-primary"><span className="text-sm font-extrabold">{new Date(event.date).getDate()}</span><span className="text-[9px]">{new Intl.DateTimeFormat('ar-EG', { month: 'short' }).format(new Date(event.date))}</span></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{event.title}</div><div className="mt-1 flex items-center gap-2 text-[11px] text-muted-foreground"><Clock3 size={12} />{event.startTime} · {event.location}</div></div><span className="hidden rounded-full bg-secondary px-2.5 py-1 text-[10px] font-semibold text-muted-foreground sm:inline">{event.type}</span></div>;
}

function StudentDashboard() {
  const { data, isLoading, isError, refetch } = useGetStudentDashboard({ query: { queryKey: getGetStudentDashboardQueryKey() } });
  if (isLoading) return <DashboardSkeleton />;
  if (isError || !data) return <QueryError onRetry={() => refetch()} />;
  const spiritual = data.spiritual;
  return <><PageIntro eyebrow="مساحة الطالب" title={`صباح الخير، ${data.user.name.split(' ')[0]}`} description="نظرة صغيرة على خطواتك هذا الأسبوع. الاستمرار أهم من الكمال." action={<Link href="/student/spiritual" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground" data-testid="link-dashboard-spiritual">سجّل يومك <ArrowLeft size={16} /></Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="التقدم الروحي" value={`${spiritual.completed}/${spiritual.total}`} detail="عادات مكتملة هذا الأسبوع" icon={HeartHandshake} /><Metric label="الحضور" value={`${data.attendance.percentage}%`} detail={`${data.attendance.attended} لقاءات حضرتها`} color="accent" icon={ClipboardCheck} /><Metric label="قراءات الإنجيل" value={data.readings.length} detail="قراءة مسجلة" icon={BookOpen} /><Metric label="الدراسات" value={data.studies.length} detail="دراسة متاحة لك" color="accent" icon={FileText} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><SectionHeader eyebrow="الخطوة اليومية" title="ملخصك الروحي" action={<Link href="/student/spiritual" className="text-xs font-bold text-primary" data-testid="link-dashboard-spiritual-more">عرض السجل</Link>} /><div className="flex flex-col gap-6 sm:flex-row sm:items-center"><div className="relative flex h-44 w-44 shrink-0 items-center justify-center self-center rounded-full" style={{ background: `conic-gradient(hsl(var(--primary)) ${spiritual.total ? (spiritual.completed / spiritual.total) * 100 : 0}%, hsl(var(--muted)) 0)` }}><div className="flex h-36 w-36 flex-col items-center justify-center rounded-full bg-card"><b className="text-4xl">{spiritual.total ? Math.round((spiritual.completed / spiritual.total) * 100) : 0}<span className="text-lg">٪</span></b><span className="mt-1 text-xs text-muted-foreground">إنجازك</span></div></div><div className="flex-1 space-y-3"><div className="flex items-center justify-between text-sm"><span>آخر اعتراف</span><b>{fmtDate(spiritual.lastConfession)}</b></div><div className="flex items-center justify-between text-sm"><span>القراءة الأخيرة</span><b>{data.readings[0] ? `${data.readings[0].book} ${data.readings[0].chapter}` : 'لم تسجل بعد'}</b></div><div className="mt-5 rounded-xl border border-primary/15 bg-primary/5 p-4 text-sm leading-7 text-muted-foreground">«اثبتوا فيَّ وأنا فيكم»<br /><span className="text-xs text-primary">يوحنا ١٥: ٤</span></div></div></div></section><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><SectionHeader eyebrow="قريباً" title="لقاءاتك القادمة" /><div>{data.events?.length ? data.events.slice(0, 4).map((event) => <EventRow key={event.id} event={event} />) : <EmptyState icon={CalendarDays} title="لا توجد لقاءات قريبة" body="سنخبرك عندما يضاف لقاء جديد لفصلك." />}</div></section></div></>;
}

function ServantDashboard() {
  const { data, isLoading, isError, refetch } = useGetServantDashboard({ query: { queryKey: getGetServantDashboardQueryKey() } });
  if (isLoading) return <DashboardSkeleton />;
  if (isError || !data) return <QueryError onRetry={() => refetch()} />;
  return <><PageIntro eyebrow="لوحة الخادم" title={`مساء الخير، ${data.user.name.split(' ')[0]}`} description="كل طالب هنا قصة تستحق أن تُرى. هذه لوحة اليوم لفصلك." action={<Link href="/servant/attendance" className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground" data-testid="link-servant-attendance">تسجيل حضور <ArrowLeft size={16} /></Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="طلاب الفصل" value={data.students.length} detail="طالباً يتابعون معك" icon={Users} /><Metric label="حضور الفصل" value={`${data.attendance.percentage}%`} detail={`${data.attendance.attended} حضوراً مسجلاً`} color="accent" icon={ClipboardCheck} /><Metric label="الدراسات النشطة" value={data.studies.length} detail="دراسة قيد المتابعة" icon={FileText} /><Metric label="إشارات اليوم" value={data.recentActivity.length} detail="تحديثات من الفصل" color="accent" icon={Zap} /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><SectionHeader eyebrow="المجتمع" title="طلابك" action={<Link href="/servant/attendance" className="text-xs font-bold text-primary" data-testid="link-students-all">كل الطلاب</Link>} /><div className="grid gap-3 sm:grid-cols-2">{data.students.slice(0, 6).map((student) => <StudentMini key={student.id} student={student} />)}</div>{!data.students.length && <EmptyState icon={Users} title="لم ينضم طلاب بعد" body="ستظهر قائمة الطلاب هنا عند ربطهم بفصلك." />}</section><section className="rounded-2xl border border-border bg-card p-5 sm:p-6"><SectionHeader eyebrow="آخر التحديثات" title="النشاط الأخير" /><div className="space-y-1">{data.recentActivity.slice(0, 5).map((activity) => <div key={activity.id} className="flex gap-3 border-b border-border/70 py-3 last:border-0"><div className="mt-1 h-2 w-2 shrink-0 rounded-full bg-primary" /><div><p className="text-sm font-semibold">{activity.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{activity.description}</p><p className="mt-1 text-[10px] text-muted-foreground">{activity.time}</p></div></div>)}</div>{!data.recentActivity.length && <EmptyState icon={Sparkles} title="لا نشاط جديد" body="ستظهر هنا التحديثات المهمة من طلابك." />}</section></div></>;
}

function StudentMini({ student }: { student: StudentSummary }) {
  return <Link href={`/servant/students/${student.id}`} className="flex items-center gap-3 rounded-xl border border-border/80 bg-background/35 p-3 transition hover:border-primary/40" data-testid={`link-student-${student.id}`}><Avatar name={student.name} size="sm" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{student.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{student.className || student.schoolYear || 'طالب'}</div></div><div className="text-left"><div className="text-xs font-extrabold text-primary">{student.attendancePercentage}%</div><div className="text-[9px] text-muted-foreground">حضور</div></div></Link>;
}

function DashboardSkeleton() {
  return <div><div className="skeleton mb-10 h-28 max-w-xl rounded-2xl" /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[1, 2, 3, 4].map((i) => <div key={i} className="skeleton h-36 rounded-2xl" />)}</div><div className="mt-6 grid gap-6 lg:grid-cols-2"><div className="skeleton h-80 rounded-2xl" /><div className="skeleton h-80 rounded-2xl" /></div></div>;
}

function Login() {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [message, setMessage] = useState('');
  const [, setLocation] = useLocation(); const login = useLogin();
  const submit = (event: React.FormEvent) => { event.preventDefault(); setMessage(''); login.mutate({ data: { email, password } }, { onSuccess: (user) => setLocation(user.role === 'SERVANT' ? '/' : '/'), onError: () => setMessage('تأكد من البريد الإلكتروني وكلمة المرور وحاول مرة أخرى.') }); };
  return <AuthLayout title="مرحباً بعودتك" subtitle="مساحتك الروحية ما زالت هنا، بانتظار خطوتك القادمة."><form onSubmit={submit} className="space-y-5"><div><Label>البريد الإلكتروني</Label><Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" required data-testid="input-login-email" /></div><div><div className="flex items-center justify-between"><Label>كلمة المرور</Label><button type="button" className="mb-2 text-xs font-bold text-primary" data-testid="button-forgot-password">نسيت كلمة المرور؟</button></div><Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required minLength={8} data-testid="input-login-password" /></div>{message && <div className="rounded-xl border border-accent/25 bg-accent/10 p-3 text-xs leading-6 text-accent" data-testid="status-login-error">{message}</div>}<Button type="submit" className="w-full" disabled={login.isPending} data-testid="button-login-submit">{login.isPending ? 'جاري الدخول...' : 'دخول إلى مساحتي'} <ArrowLeft size={16} /></Button></form><div className="mt-7 border-t border-border pt-6 text-center text-sm text-muted-foreground">ليس لديك حساب؟ <Link href="/signup" className="font-bold text-primary" data-testid="link-login-signup">أنشئ حساباً</Link></div></AuthLayout>;
}

function AuthLayout({ title, subtitle, children }: { title: string; subtitle: string; children: React.ReactNode }) {
  return <div className="thanwy-grid flex min-h-[100dvh] items-center justify-center bg-background px-5 py-8"><div className="w-full max-w-md"><div className="mb-9 flex justify-center"><Link href="/" data-testid="link-auth-logo"><ThanwyLogo /></Link></div><div className="rounded-[1.7rem] border border-border bg-card/85 p-6 shadow-2xl shadow-primary/5 backdrop-blur sm:p-9"><div className="mb-8"><div className="mb-3 text-[10px] font-bold uppercase tracking-[.22em] text-primary">THANWY / MEETINGS</div><h1 className="text-3xl font-extrabold">{title}</h1><p className="mt-3 text-sm leading-7 text-muted-foreground">{subtitle}</p></div>{children}</div><p className="mt-6 text-center text-[11px] text-muted-foreground">مساحة ثانوي مصممة لتساعدك أن تكمل بأمانة.</p></div></div>;
}

function Signup() {
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [year, setYear] = useState(''); const [classId, setClassId] = useState(''); const [message, setMessage] = useState('');
  const signup = useSignup(); const [, setLocation] = useLocation();
  const classes = useMemo(() => year ? ({
    'أولى سنوي': [{ id: 'class-athanasius', name: 'البابا أثناسيوس' }, { id: 'class-peter', name: 'البابا بطرس' }],
    'تانية سنوي': [{ id: 'class-polycarp', name: 'القديس بوليكاربوس' }, { id: 'class-titus', name: 'القديس تيتوس' }],
    'تالتة سنوي': [{ id: 'class-david', name: 'فصل داود النبي' }],
  }[year] || []) : [], [year]);
  const getErrorMessage = (error: unknown) => {
    const response = (error as { response?: { data?: { error?: string } } })?.response;
    return response?.data?.error || 'تعذر إنشاء الحساب. راجع البيانات وحاول مرة أخرى.';
  };
  const submit = (event: React.FormEvent) => { event.preventDefault(); setMessage(''); signup.mutate({ data: { name: name.trim(), email: email.trim().toLowerCase(), password, schoolYear: year, classId } }, { onSuccess: () => setLocation('/'), onError: (error) => setMessage(getErrorMessage(error)) }); };
  return <AuthLayout title="ابدأ من هنا" subtitle="أنشئ حسابك كطالب، وخلي كل أحد له معنى أبعد."><form onSubmit={submit} className="space-y-4"><div><Label>الاسم بالكامل</Label><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="اكتب اسمك" minLength={2} required data-testid="input-signup-name" /></div><div><Label>البريد الإلكتروني</Label><Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" required data-testid="input-signup-email" /></div><div><Label>كلمة المرور</Label><Input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="٨ أحرف على الأقل" minLength={8} required data-testid="input-signup-password" /></div><div className="grid gap-4 sm:grid-cols-2"><div><Label>السنة الدراسية</Label><div className="relative"><Select value={year} onChange={(e) => { setYear(e.target.value); setClassId(''); }} required data-testid="select-signup-year"><option value="">اختر السنة</option><option value="أولى سنوي">الصف الأول الثانوي</option><option value="تانية سنوي">الصف الثاني الثانوي</option><option value="تالتة سنوي">الصف الثالث الثانوي</option></Select><ChevronDown className="pointer-events-none absolute left-3 top-4 text-muted-foreground" size={16} /></div></div><div><Label>الفصل</Label><div className="relative"><Select value={classId} onChange={(e) => setClassId(e.target.value)} required disabled={!year} data-testid="select-signup-class"><option value="">{year ? 'اختر الفصل' : 'اختر السنة أولاً'}</option>{classes.map((option) => <option key={option.id} value={option.id}>{option.name}</option>)}</Select><ChevronDown className="pointer-events-none absolute left-3 top-4 text-muted-foreground" size={16} /></div></div></div>{message && <div className="rounded-xl border border-accent/25 bg-accent/10 p-3 text-xs text-accent" data-testid="status-signup-error">{message}</div>}<Button type="submit" className="mt-2 w-full" disabled={signup.isPending} data-testid="button-signup-submit">{signup.isPending ? 'جاري إنشاء الحساب...' : 'إنشاء حسابي'} <ArrowLeft size={16} /></Button></form><div className="mt-7 border-t border-border pt-6 text-center text-sm text-muted-foreground">لديك حساب بالفعل؟ <Link href="/login" className="font-bold text-primary" data-testid="link-signup-login">سجّل الدخول</Link></div></AuthLayout>;
}

function SpiritualPage() {
  const { data: records, isLoading, isError, refetch } = useListSpiritualRecords(undefined, { query: { queryKey: getListSpiritualRecordsQueryKey(), retry: false } });
  const create = useCreateSpiritualRecord(); const qc = useQueryClient(); const today = new Date().toISOString().slice(0, 10);
  const latest = records?.[0]; const [date, setDate] = useState(today); const [checks, setChecks] = useState({ morningPrayer: false, vespersPrayer: false, sleepPrayer: false, spontaneousPrayer: false, communion: false }); const [confessionDate, setConfessionDate] = useState(''); const [feedback, setFeedback] = useState('');
  const toggle = (key: keyof typeof checks) => setChecks((current) => ({ ...current, [key]: !current[key] }));
  const save = () => { setFeedback(''); create.mutate({ data: { date, ...checks, confessionDate: confessionDate || null } }, { onSuccess: () => { setFeedback('تم حفظ يومك الروحي'); qc.invalidateQueries({ queryKey: getListSpiritualRecordsQueryKey() }); qc.invalidateQueries({ queryKey: getGetStudentDashboardQueryKey() }); }, onError: () => setFeedback('لم يتم الحفظ. حاول مرة أخرى.') }); };
  if (isLoading) return <PageSkeleton />; if (isError) return <QueryError onRetry={() => refetch()} />;
  const habits: Array<[keyof typeof checks, string, string]> = [['morningPrayer', 'صلاة باكر', 'ابدأ يومك بحضور'], ['vespersPrayer', 'صلاة الغروب', 'توقف واستعد'], ['sleepPrayer', 'صلاة النوم', 'اختم يومك بسلام'], ['spontaneousPrayer', 'صلاة عابرة', 'ارفع قلبك في أي وقت'], ['communion', 'التناول', 'ثبت في الشركة']];
  return <><PageIntro eyebrow="رحلة الداخل" title="حياتي الروحية" description="لا نسجل أرقاماً فقط؛ ننتبه للحضور. اختر يوماً وسجّل ما عشته بصدق." /><div className="grid gap-6 xl:grid-cols-[.95fr_1.05fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="هذا اليوم" title="كيف كان يومك؟" /><div className="mb-6"><Label>التاريخ</Label><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} data-testid="input-spiritual-date" /></div><div className="space-y-2">{habits.map(([key, label, hint]) => <button key={key} type="button" onClick={() => toggle(key)} className={cn('flex min-h-[70px] w-full items-center gap-4 rounded-xl border p-4 text-right transition', checks[key] ? 'border-primary/40 bg-primary/10' : 'border-border bg-background/25 hover:border-primary/30')} data-testid={`button-spiritual-${key}`}><span className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border', checks[key] ? 'border-primary bg-primary text-primary-foreground' : 'border-border text-transparent')}><Check size={16} /></span><span className="flex-1"><b className="block text-sm">{label}</b><small className="mt-1 block text-xs text-muted-foreground">{hint}</small></span></button>)}</div><div className="mt-6"><Label>تاريخ آخر اعتراف</Label><Input type="date" value={confessionDate} onChange={(e) => setConfessionDate(e.target.value)} data-testid="input-confession-date" /></div>{feedback && <div className={cn('mt-4 rounded-xl p-3 text-xs font-semibold', feedback.includes('لم') ? 'bg-accent/10 text-accent' : 'bg-primary/10 text-primary')} data-testid="status-spiritual-feedback">{feedback}</div>}<Button onClick={save} disabled={create.isPending} className="mt-5 w-full" data-testid="button-save-spiritual">{create.isPending ? 'جاري الحفظ...' : 'حفظ يومي'} <Check size={16} /></Button></section><section><div className="rounded-2xl border border-primary/20 bg-primary/5 p-6"><div className="mb-5 flex items-start justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">ثبات هادئ</div><h2 className="mt-2 text-2xl font-extrabold">أنت لا تبدأ من الصفر</h2></div><Moon className="text-primary" /></div><p className="text-sm leading-8 text-muted-foreground">كل مرة تفتح فيها قلبك للصلاة هي عودة. استمر في تسجيل ما يحييك، حتى في الأيام الصغيرة.</p></div><div className="mt-6 rounded-2xl border border-border bg-card p-5"><SectionHeader eyebrow="سجل الأيام" title="آخر ما سجلت" />{records?.length ? <div>{records.slice(0, 7).map((record) => <SpiritualRow key={record.id} record={record} />)}</div> : <EmptyState icon={HeartHandshake} title="السجل ما زال فارغاً" body="سجّل أول يوم لك، وستبدأ الصورة في الظهور." />}</div></section></div></>;
}

function SpiritualRow({ record }: { record: SpiritualRecord }) {
  const count = [record.morningPrayer, record.vespersPrayer, record.sleepPrayer, record.spontaneousPrayer, record.communion].filter(Boolean).length;
  return <div className="flex items-center gap-3 border-b border-border/70 py-3 last:border-0"><div className="flex h-10 w-10 shrink-0 flex-col items-center justify-center rounded-lg bg-secondary text-[10px] font-bold"><span className="text-sm">{new Date(record.date).getDate()}</span><span>{new Intl.DateTimeFormat('ar-EG', { month: 'short' }).format(new Date(record.date))}</span></div><div className="flex-1"><div className="text-sm font-bold">{fmtLongDate(record.date)}</div><div className="mt-1 text-[10px] text-muted-foreground">{record.confessionDate ? `اعتراف ${fmtDate(record.confessionDate)}` : 'لا يوجد اعتراف مسجل'}</div></div><div className="text-xs font-extrabold text-primary">{count}/٥</div></div>;
}

const bibleBooks = { 'العهد القديم': ['التكوين', 'الخروج', 'المزامير', 'الأمثال', 'إشعياء'], 'العهد الجديد': ['متى', 'مرقس', 'لوقا', 'يوحنا', 'أعمال الرسل', 'رومية'] };
function BiblePage() {
  const { data: readings, isLoading, isError, refetch } = useListBibleReadings(undefined, { query: { queryKey: getListBibleReadingsQueryKey(), retry: false } });
  const create = useCreateBibleReading(); const update = useUpdateBibleReading(); const remove = useDeleteBibleReading(); const qc = useQueryClient();
  const [editing, setEditing] = useState<BibleReading | null>(null); const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [testament, setTestament] = useState('العهد الجديد'); const [book, setBook] = useState(''); const [chapter, setChapter] = useState(''); const [note, setNote] = useState(''); const [feedback, setFeedback] = useState('');
  const books = bibleBooks[testament as keyof typeof bibleBooks] || [];
  const startEdit = (reading: BibleReading) => { setEditing(reading); setDate(reading.date.slice(0, 10)); setTestament(reading.testament); setBook(reading.book); setChapter(String(reading.chapter)); setNote(reading.note || ''); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const reset = () => { setEditing(null); setDate(new Date().toISOString().slice(0, 10)); setTestament('العهد الجديد'); setBook(''); setChapter(''); setNote(''); };
  const save = () => { const payload = { date, testament, book, chapter: Number(chapter), note: note || null }; setFeedback(''); const onDone = () => { setFeedback('تم حفظ القراءة بنجاح'); qc.invalidateQueries({ queryKey: getListBibleReadingsQueryKey() }); qc.invalidateQueries({ queryKey: getGetStudentDashboardQueryKey() }); reset(); }; if (editing) update.mutate({ id: editing.id, data: payload }, { onSuccess: onDone, onError: () => setFeedback('تعذر تعديل القراءة.') }); else create.mutate({ data: payload }, { onSuccess: onDone, onError: () => setFeedback('تعذر حفظ القراءة.') }); };
  if (isLoading) return <PageSkeleton />; if (isError) return <QueryError onRetry={() => refetch()} />;
  return <><PageIntro eyebrow="كلمة اليوم" title="قراءة الكتاب" description="صفحة واحدة بتركيز، أفضل من فصول كثيرة بلا حضور." action={<span className="hidden items-center gap-2 rounded-xl border border-primary/20 bg-primary/5 px-3 py-2 text-xs font-bold text-primary sm:flex"><BookOpen size={15} /> {readings?.length || 0} قراءات مسجلة</span>} /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow={editing ? 'تعديل' : 'تسجيل جديد'} title={editing ? 'عدّل قراءتك' : 'ماذا قرأت اليوم؟'} action={editing && <Button variant="ghost" onClick={reset} className="px-2 text-xs">إلغاء</Button>} /><div className="space-y-4"><div><Label>التاريخ</Label><Input type="date" value={date} onChange={(e) => setDate(e.target.value)} data-testid="input-reading-date" /></div><div><Label>العهد</Label><div className="grid grid-cols-2 gap-2">{Object.keys(bibleBooks).map((item) => <button key={item} type="button" onClick={() => { setTestament(item); setBook(''); }} className={cn('min-h-11 rounded-xl border text-xs font-bold', testament === item ? 'border-primary bg-primary/10 text-primary' : 'border-border text-muted-foreground')} data-testid={`button-testament-${item}`}>{item}</button>)}</div></div><div><Label>السفر</Label><Select value={book} onChange={(e) => setBook(e.target.value)} data-testid="select-reading-book"><option value="">اختر السفر</option>{books.map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>الإصحاح</Label><Select value={chapter} onChange={(e) => setChapter(e.target.value)} disabled={!book} data-testid="select-reading-chapter"><option value="">اختر الإصحاح</option>{Array.from({ length: 30 }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1}</option>)}</Select></div><div><Label>ملاحظة صغيرة <span className="font-normal">اختياري</span></Label><textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="ما الذي لمسك اليوم؟" className="min-h-24 w-full resize-none rounded-xl border border-input bg-background/70 p-4 text-sm outline-none focus:border-primary" data-testid="textarea-reading-note" /></div>{feedback && <div className="rounded-xl bg-primary/10 p-3 text-xs font-semibold text-primary" data-testid="status-reading-feedback">{feedback}</div>}<Button onClick={save} disabled={!book || !chapter || (create.isPending || update.isPending)} className="w-full" data-testid="button-save-reading">{editing ? 'حفظ التعديل' : 'تسجيل القراءة'} <Check size={16} /></Button></div></section><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="ذاكرة الكلمة" title="سجل قراءاتك" />{readings?.length ? <div className="space-y-1">{readings.map((reading) => <div key={reading.id} className="group flex items-center gap-3 rounded-xl border-b border-border/70 py-4 last:border-0" data-testid={`reading-row-${reading.id}`}><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-accent/10 text-accent"><BookOpen size={18} /></div><div className="min-w-0 flex-1"><div className="text-sm font-bold">{reading.book} <span className="text-primary">٣٦:{reading.chapter}</span></div><div className="mt-1 truncate text-xs text-muted-foreground">{fmtDate(reading.date)} {reading.note ? `· ${reading.note}` : ''}</div></div><div className="flex gap-1 opacity-100 transition sm:opacity-0 sm:group-hover:opacity-100"><Button variant="ghost" onClick={() => startEdit(reading)} className="h-9 min-h-9 px-2 text-xs" data-testid={`button-edit-reading-${reading.id}`}>تعديل</Button><Button variant="ghost" onClick={() => remove.mutate({ id: reading.id }, { onSuccess: () => qc.invalidateQueries({ queryKey: getListBibleReadingsQueryKey() }) })} className="h-9 min-h-9 px-2 text-accent" data-testid={`button-delete-reading-${reading.id}`}><Trash2 size={15} /></Button></div></div>)}</div> : <EmptyState icon={BookOpen} title="لم تسجل قراءة بعد" body="ابدأ بقراءة قصيرة، ثم اترك لها أثراً هنا." />}</section></div></>;
}

function AttendancePage() {
  const { data, isLoading, isError, refetch } = useGetAttendance(undefined, { query: { queryKey: getGetAttendanceQueryKey(), retry: false } });
  if (isLoading) return <PageSkeleton />; if (isError || !data) return <QueryError onRetry={() => refetch()} />;
  return <><PageIntro eyebrow="وجودك يصنع فرقاً" title="الحضور" description="كل لقاء تحضره هو مساحة جديدة للنمو مع إخوتك." /><div className="grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><section className="rounded-2xl border border-primary/20 bg-primary/5 p-6 sm:p-8"><div className="flex items-start justify-between"><div><div className="text-xs font-bold text-primary">نسبة حضورك</div><div className="mt-4 text-6xl font-extrabold tracking-tight">{data.percentage}<span className="text-2xl">٪</span></div><p className="mt-2 text-xs text-muted-foreground">استمر، أنت قريب من هدفك</p></div><ClipboardCheck className="text-primary" size={24} /></div><div className="mt-8 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${data.percentage}%` }} /></div><div className="mt-4 flex justify-between text-xs text-muted-foreground"><span>{data.attended} حضور</span><span>{data.missed} غياب</span></div></section><section className="rounded-2xl border border-border bg-card p-6 sm:p-8"><div className="mb-6 flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">بطاقة التعريف</div><h2 className="mt-2 text-xl font-extrabold">بطاقتك في ثانوي</h2></div><QrCode className="text-primary" size={27} /></div><div className="flex flex-col items-center gap-5 rounded-2xl border border-border bg-background/50 p-6 sm:flex-row"><div className="flex h-28 w-28 items-center justify-center border-4 border-primary/60 bg-card" style={{ backgroundImage: 'linear-gradient(45deg, hsl(var(--primary)/.18) 25%, transparent 25%, transparent 75%, hsl(var(--primary)/.18) 75%), linear-gradient(45deg, hsl(var(--primary)/.18) 25%, transparent 25%, transparent 75%, hsl(var(--primary)/.18) 75%)', backgroundSize: '12px 12px', backgroundPosition: '0 0, 6px 6px' }}><QrCode size={50} className="text-primary" /></div><div className="text-center sm:text-right"><div className="text-lg font-extrabold">ثانوي ميتنجز</div><div className="mt-2 text-sm text-muted-foreground">اعرض هذه البطاقة عند تسجيل الحضور</div><div className="mt-3 font-mono text-xs text-primary">TNW / STUDENT / ACTIVE</div></div></div></section></div><section className="mt-6 rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="الذاكرة" title="سجل اللقاءات" />{data.records?.length ? <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead><tr className="border-b border-border text-xs text-muted-foreground"><th className="pb-3 font-semibold">اللقاء</th><th className="pb-3 font-semibold">التاريخ</th><th className="pb-3 font-semibold">الحالة</th></tr></thead><tbody>{data.records.map((record) => <tr key={record.id} className="border-b border-border/60 last:border-0"><td className="py-4 font-bold">{record.eventTitle}</td><td className="py-4 text-muted-foreground">{fmtDate(record.date)}</td><td className="py-4"><span className={cn('rounded-full px-3 py-1 text-[10px] font-bold', record.status === 'present' ? 'bg-primary/10 text-primary' : 'bg-accent/10 text-accent')}>{record.status === 'present' ? 'حاضر' : 'غائب'}</span></td></tr>)}</tbody></table></div> : <EmptyState icon={CalendarDays} title="لا توجد سجلات بعد" body="ستظهر لقاءاتك هنا بعد أول تسجيل حضور." />}</section></>;
}

function StudiesPage() {
  const { data: studies, isLoading, isError, refetch } = useListBibleStudies({ query: { queryKey: getListBibleStudiesQueryKey(), retry: false } });
  const [selected, setSelected] = useState<string | null>(null); const detail = useGetBibleStudy(selected || '', { query: { enabled: !!selected, queryKey: getGetBibleStudyQueryKey(selected || '') } }); const submit = useSubmitBibleStudy(); const qc = useQueryClient(); const [answer, setAnswer] = useState(''); const [feedback, setFeedback] = useState('');
  if (isLoading) return <PageSkeleton />; if (isError) return <QueryError onRetry={() => refetch()} />;
  const active = studies?.find((study) => study.id === selected);
  const send = () => { if (!selected) return; submit.mutate({ id: selected, data: { answers: detail.data?.questions?.map((q) => ({ questionId: q.id, answer })) || [] } }, { onSuccess: () => { setFeedback('تم تسليم الدراسة للخادم'); qc.invalidateQueries({ queryKey: getListBibleStudiesQueryKey() }); }, onError: () => setFeedback('تعذر التسليم حالياً.') }); };
  return <><PageIntro eyebrow="نتعلم معاً" title="الدراسات الكتابية" description="اقرأ، تأمل، ثم شارك ما فهمته. النمو يصبح أجمل عندما نضعه في كلمات." /><div className="grid gap-6 lg:grid-cols-[.9fr_1.1fr]"><section className="space-y-3">{studies?.map((study) => <button key={study.id} onClick={() => { setSelected(study.id); setFeedback(''); }} className={cn('w-full rounded-2xl border p-5 text-right transition', selected === study.id ? 'border-primary/50 bg-primary/5' : 'border-border bg-card hover:border-primary/30')} data-testid={`button-study-${study.id}`}><div className="mb-4 flex items-start justify-between gap-3"><span className="rounded-full bg-secondary px-2.5 py-1 text-[10px] font-bold text-muted-foreground">{study.status === 'active' ? 'قيد الدراسة' : study.status}</span><FileText className="text-primary" size={19} /></div><h3 className="font-extrabold">{study.title}</h3><p className="mt-2 line-clamp-2 text-xs leading-6 text-muted-foreground">{study.description}</p><div className="mt-4 flex items-center justify-between text-[10px] text-muted-foreground"><span>{study.book} {study.chapter}</span><span>آخر موعد {fmtDate(study.deadline)}</span></div></button>)}{!studies?.length && <EmptyState icon={FileText} title="لا توجد دراسات متاحة" body="ستظهر تكليفات خادمك هنا." />}</section><section className="rounded-2xl border border-border bg-card p-6 sm:p-8">{active ? <><div className="mb-7 flex items-start justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.2em] text-primary">الدراسة المختارة</div><h2 className="mt-2 text-2xl font-extrabold">{active.title}</h2></div><Button variant="ghost" onClick={() => setSelected(null)} className="h-9 min-h-9 px-2"><X size={17} /></Button></div><p className="mb-7 text-sm leading-7 text-muted-foreground">{active.description}</p>{detail.isLoading ? <div className="skeleton h-32 rounded-xl" /> : <div><Label>تأملك</Label><textarea value={answer} onChange={(e) => setAnswer(e.target.value)} placeholder="اكتب ما فهمته وما لمسك..." className="min-h-40 w-full resize-none rounded-xl border border-input bg-background/70 p-4 text-sm leading-7 outline-none focus:border-primary" data-testid="textarea-study-answer" /><div className="mt-4 flex items-center justify-between"><span className="text-xs text-muted-foreground">موعد التسليم: {fmtLongDate(active.deadline)}</span><Button onClick={send} disabled={!answer || submit.isPending} data-testid="button-submit-study">{submit.isPending ? 'جاري التسليم...' : 'تسليم الدراسة'} <ArrowLeft size={16} /></Button></div>{feedback && <div className="mt-4 rounded-xl bg-primary/10 p-3 text-xs font-semibold text-primary" data-testid="status-study-feedback">{feedback}</div>}</div>}</> : <div className="flex min-h-[360px] flex-col items-center justify-center text-center"><div className="mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 text-primary"><FileText size={28} /></div><h2 className="text-xl font-extrabold">اختر دراسة لتبدأ</h2><p className="mt-3 max-w-xs text-sm leading-7 text-muted-foreground">اختر واحدة من الدراسات على اليمين لتقرأ التفاصيل وتشارك تأملك.</p></div>}</section></div></>;
}

function ServantAttendancePage() {
  const { data: events, isLoading: eventsLoading } = useListEvents({ query: { queryKey: getListEventsQueryKey(), retry: false } }); const { data: students, isLoading: studentsLoading } = useListClassStudents({ query: { queryKey: getListClassStudentsQueryKey(), retry: false } }); const checkIn = useCheckInStudent(); const qc = useQueryClient(); const [eventId, setEventId] = useState(''); const [token, setToken] = useState(''); const [feedback, setFeedback] = useState('');
  const submit = () => { checkIn.mutate({ data: { eventId, qrToken: token } }, { onSuccess: () => { setFeedback('تم تسجيل الحضور بنجاح'); setToken(''); qc.invalidateQueries({ queryKey: getGetAttendanceQueryKey() }); }, onError: () => setFeedback('لم يتم التعرف على البطاقة. راجع الرمز وحاول.') }); };
  return <><PageIntro eyebrow="إدارة الفصل" title="تسجيل الحضور" description="اختر اللقاء، ثم امسح بطاقة الطالب أو أدخل الرمز الخاص بها." action={<Link href="/student/attendance" className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-border bg-card px-4 text-xs font-bold" data-testid="link-attendance-student-view">عرض بطاقتي <ArrowLeft size={15} /></Link>} /><div className="grid gap-6 xl:grid-cols-[.8fr_1.2fr]"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="الآن" title="نقطة الدخول" /><div className="mb-5"><Label>اللقاء</Label><Select value={eventId} onChange={(e) => setEventId(e.target.value)} disabled={eventsLoading} data-testid="select-attendance-event"><option value="">اختر اللقاء</option>{events?.map((event) => <option key={event.id} value={event.id}>{event.title} · {fmtDate(event.date)}</option>)}</Select></div><div className="rounded-2xl border border-dashed border-primary/30 bg-primary/5 p-7 text-center"><QrCode className="mx-auto mb-3 text-primary" size={38} /><div className="font-bold">منطقة مسح بطاقة الطالب</div><p className="mt-2 text-xs leading-6 text-muted-foreground">يمكن ربط قارئ الكاميرا هنا. أدخل رمز البطاقة يدوياً الآن.</p><Input value={token} onChange={(e) => setToken(e.target.value)} placeholder="رمز بطاقة الطالب" className="mt-5 text-center" data-testid="input-checkin-token" /></div>{feedback && <div className={cn('mt-4 rounded-xl p-3 text-xs font-semibold', feedback.includes('لم') ? 'bg-accent/10 text-accent' : 'bg-primary/10 text-primary')} data-testid="status-checkin-feedback">{feedback}</div>}<Button onClick={submit} disabled={!eventId || !token || checkIn.isPending} className="mt-5 w-full" data-testid="button-checkin-submit">{checkIn.isPending ? 'جاري التسجيل...' : 'تسجيل حضور الطالب'} <Check size={16} /></Button></section><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="الفصل" title="طلابك" action={<span className="rounded-full bg-secondary px-3 py-1 text-[10px] font-bold text-muted-foreground">{students?.length || 0} طلاب</span>} />{studentsLoading ? <div className="space-y-3">{[1, 2, 3].map((i) => <div key={i} className="skeleton h-16 rounded-xl" />)}</div> : students?.length ? <div className="space-y-2">{students.map((student) => <StudentMini key={student.id} student={student} />)}</div> : <EmptyState icon={Users} title="لم يضف طلاب بعد" body="ستظهر القائمة عند ربط طلاب الفصل." />}</section></div></>;
}

function StudentPicker({ selected, onSelect }: { selected: string; onSelect: (id: string) => void }) {
  const { data: students } = useListClassStudents({ query: { queryKey: getListClassStudentsQueryKey(), retry: false } });
  return <div className="relative"><Search className="pointer-events-none absolute right-3 top-4 text-muted-foreground" size={16} /><Select value={selected} onChange={(e) => onSelect(e.target.value)} className="pr-10" data-testid="select-servant-student"><option value="">اختر طالباً للمتابعة</option>{students?.map((student) => <option key={student.id} value={student.id}>{student.name}</option>)}</Select></div>;
}

function ServantSpiritualPage() {
  const [selected, setSelected] = useState(''); const { data, isLoading, isError } = useListSpiritualRecords({ studentId: selected || undefined }, { query: { enabled: !!selected, queryKey: getListSpiritualRecordsQueryKey({ studentId: selected || undefined }) } });
  return <><PageIntro eyebrow="رعاية فردية" title="المتابعة الروحية" description="انظر إلى الصورة كاملة، واقترب من كل طالب بالانتباه المناسب." /><div className="mb-6 max-w-md"><Label>الطالب</Label><StudentPicker selected={selected} onSelect={setSelected} /></div>{!selected ? <EmptyState icon={Users} title="اختر طالباً" body="اختر طالباً من القائمة لترى سجله الروحي الأسبوعي." /> : isLoading ? <PageSkeleton /> : isError ? <QueryError /> : <section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="السجل الأسبوعي" title="أيام الحضور الداخلي" /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{data?.map((record) => <div key={record.id} className="rounded-xl border border-border bg-background/30 p-4"><div className="flex items-center justify-between"><span className="text-xs font-bold">{fmtDate(record.date)}</span><span className="text-[10px] text-primary">{[record.morningPrayer, record.vespersPrayer, record.sleepPrayer, record.spontaneousPrayer, record.communion].filter(Boolean).length}/٥</span></div><div className="mt-4 flex flex-wrap gap-1.5">{[['باكر', record.morningPrayer], ['غروب', record.vespersPrayer], ['نوم', record.sleepPrayer], ['عابرة', record.spontaneousPrayer], ['تناول', record.communion]].map(([label, value]) => <span key={String(label)} className={cn('rounded-md px-2 py-1 text-[10px] font-bold', value ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground')}>{String(label)}</span>)}</div>{record.confessionDate && <div className="mt-4 border-t border-border pt-3 text-[10px] text-muted-foreground">آخر اعتراف: {fmtDate(record.confessionDate)}</div>}</div>)}</div>{!data?.length && <EmptyState icon={HeartHandshake} title="لا يوجد سجل بعد" body="لم يسجل هذا الطالب أياماً روحية بعد." />}</section>}</>;
}

function ServantReadingsPage() {
  const [selected, setSelected] = useState(''); const [filter, setFilter] = useState<'all' | 'week' | 'month' | 'old' | 'new'>('all'); const { data, isLoading, isError } = useListBibleReadings({ studentId: selected || undefined, filter }, { query: { enabled: !!selected, queryKey: getListBibleReadingsQueryKey({ studentId: selected || undefined, filter }) } });
  return <><PageIntro eyebrow="أثر الكلمة" title="قراءات الطلاب" description="ساعد طلابك أن يلاحظوا علاقتهم بالكلمة، لا أن يحولوها إلى قائمة مهام." /><div className="mb-6 grid gap-4 sm:grid-cols-[minmax(220px,320px)_1fr]"><div><Label>الطالب</Label><StudentPicker selected={selected} onSelect={setSelected} /></div>{selected && <div><Label>تصفية السجل</Label><div className="flex flex-wrap gap-2">{[['all', 'الكل'], ['week', 'هذا الأسبوع'], ['month', 'هذا الشهر'], ['old', 'العهد القديم'], ['new', 'العهد الجديد']].map(([key, label]) => <button key={key} onClick={() => setFilter(key as typeof filter)} className={cn('min-h-11 rounded-xl border px-3 text-xs font-bold', filter === key ? 'border-primary bg-primary/10 text-primary' : 'border-border bg-card text-muted-foreground')} data-testid={`button-filter-${key}`}>{label}</button>)}</div></div>}</div>{!selected ? <EmptyState icon={BookOpen} title="اختر طالباً" body="اختر طالباً لرؤية تاريخ قراءاته وفترات انتظامه." /> : isLoading ? <PageSkeleton /> : isError ? <QueryError /> : <section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="السجل" title="القراءات المسجلة" action={<span className="text-xs text-muted-foreground">{data?.length || 0} قراءة</span>} />{data?.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{data.map((reading) => <div key={reading.id} className="rounded-xl border border-border bg-background/30 p-4"><div className="flex items-start justify-between"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent/10 text-accent"><BookOpen size={16} /></div><span className="text-[10px] text-muted-foreground">{fmtDate(reading.date)}</span></div><h3 className="mt-4 text-sm font-extrabold">{reading.book} {reading.chapter}</h3>{reading.note && <p className="mt-2 text-xs leading-6 text-muted-foreground">«{reading.note}»</p>}</div>)}</div> : <EmptyState icon={BookOpen} title="لا توجد قراءات" body="لم يسجل هذا الطالب قراءات ضمن التصفية الحالية." />}</section>}</>;
}

function ServantStudiesPage() {
  const { data: studies, isLoading, isError, refetch } = useListBibleStudies({ query: { queryKey: getListBibleStudiesQueryKey(), retry: false } }); const create = useCreateBibleStudy(); const qc = useQueryClient(); const [open, setOpen] = useState(false); const [title, setTitle] = useState(''); const [description, setDescription] = useState(''); const [book, setBook] = useState(''); const [chapter, setChapter] = useState(''); const [deadline, setDeadline] = useState(''); const [feedback, setFeedback] = useState('');
  const save = () => { create.mutate({ data: { title, description, testament: 'العهد الجديد', book, chapter: Number(chapter), startDate: new Date().toISOString().slice(0, 10), deadline, questions: [{ question: 'ما الذي لمسك في هذه الدراسة؟', type: 'long', order: 1 }] } }, { onSuccess: () => { setOpen(false); setTitle(''); setDescription(''); setBook(''); setChapter(''); setDeadline(''); setFeedback('تم إنشاء الدراسة'); qc.invalidateQueries({ queryKey: getListBibleStudiesQueryKey() }); }, onError: () => setFeedback('تعذر إنشاء الدراسة.') }); };
  if (isLoading) return <PageSkeleton />; if (isError) return <QueryError onRetry={() => refetch()} />;
  return <><PageIntro eyebrow="تكوين ونمو" title="الدراسات الكتابية" description="صمّم مساحات صغيرة تجعل طلابك يقرأون ويفكرون ويشاركون." action={<Button onClick={() => setOpen((value) => !value)} data-testid="button-open-create-study"><Plus size={17} /> دراسة جديدة</Button>} />{open && <section className="mb-6 rounded-2xl border border-primary/25 bg-primary/5 p-5 sm:p-7"><SectionHeader eyebrow="إنشاء" title="دراسة جديدة" action={<Button variant="ghost" onClick={() => setOpen(false)}><X size={16} /></Button>} /><div className="grid gap-4 md:grid-cols-2"><div><Label>عنوان الدراسة</Label><Input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="مثال: المحبة التي تتحرك" data-testid="input-study-title" /></div><div><Label>السفر</Label><Select value={book} onChange={(e) => setBook(e.target.value)} data-testid="select-study-book"><option value="">اختر السفر</option>{bibleBooks['العهد الجديد'].map((item) => <option key={item}>{item}</option>)}</Select></div><div><Label>الإصحاح</Label><Input type="number" min="1" value={chapter} onChange={(e) => setChapter(e.target.value)} placeholder="١" data-testid="input-study-chapter" /></div><div><Label>موعد التسليم</Label><Input type="date" value={deadline} onChange={(e) => setDeadline(e.target.value)} data-testid="input-study-deadline" /></div><div className="md:col-span-2"><Label>وصف مختصر</Label><textarea value={description} onChange={(e) => setDescription(e.target.value)} className="min-h-24 w-full resize-none rounded-xl border border-input bg-background/70 p-4 text-sm outline-none focus:border-primary" placeholder="ما الذي نريد أن نراه في هذه الدراسة؟" data-testid="textarea-study-description" /></div></div>{feedback && <div className="mt-4 text-xs font-bold text-accent">{feedback}</div>}<Button onClick={save} disabled={!title || !book || !chapter || !deadline || create.isPending} className="mt-5" data-testid="button-create-study">{create.isPending ? 'جاري الإنشاء...' : 'إنشاء الدراسة'} <Check size={16} /></Button></section>}<section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="المكتبة" title="كل الدراسات" />{studies?.length ? <div className="grid gap-4 md:grid-cols-2">{studies.map((study) => <div key={study.id} className="rounded-2xl border border-border bg-background/25 p-5"><div className="flex items-start justify-between"><span className="rounded-full bg-primary/10 px-2.5 py-1 text-[10px] font-bold text-primary">{study.status === 'active' ? 'نشطة' : study.status}</span><FileText size={19} className="text-primary" /></div><h3 className="mt-5 text-lg font-extrabold">{study.title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{study.description}</p><div className="mt-6 flex items-center justify-between border-t border-border pt-4 text-xs"><span>{study.submittedCount} من {study.totalStudents} سلّموا</span><span className="text-muted-foreground">حتى {fmtDate(study.deadline)}</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${study.totalStudents ? (study.submittedCount / study.totalStudents) * 100 : 0}%` }} /></div></div>)}</div> : <EmptyState icon={FileText} title="لم تنشئ دراسة بعد" body="أنشئ أول دراسة قصيرة لفصلك وابدأ الحوار." />}</section></>;
}

function StudentProfilePage() {
  const { id = '' } = useParams<{ id: string }>(); const { data, isLoading, isError, refetch } = useGetStudentProfile(id, { query: { enabled: !!id, queryKey: getGetStudentProfileQueryKey(id) } });
  if (isLoading) return <PageSkeleton />; if (isError || !data) return <QueryError onRetry={() => refetch()} />;
  return <><Link href="/servant/attendance" className="mb-7 inline-flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary" data-testid="link-profile-back"><ArrowRight size={15} /> العودة إلى الطلاب</Link><div className="mb-9 flex flex-col gap-5 sm:flex-row sm:items-center"><Avatar name={data.name} size="lg" /><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.2em] text-primary">ملف الطالب</div><h1 className="text-3xl font-extrabold">{data.name}</h1><p className="mt-2 text-sm text-muted-foreground">{data.schoolYear} · {data.className}</p></div></div><div className="grid gap-4 sm:grid-cols-3"><Metric label="الحضور" value={`${data.attendancePercentage}%`} icon={ClipboardCheck} /><Metric label="الروحيات" value={`${data.spiritualPercentage}%`} color="accent" icon={HeartHandshake} /><Metric label="آخر نشاط" value={fmtDate(data.lastActivity)} icon={Clock3} /></div><div className="mt-6 grid gap-6 xl:grid-cols-2"><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="الروحيات" title="آخر السجلات" />{data.spiritualRecords?.length ? data.spiritualRecords.slice(0, 5).map((record) => <SpiritualRow key={record.id} record={record} />) : <EmptyState icon={HeartHandshake} title="لا سجلات بعد" body="لم يسجل الطالب أياماً روحية." />}</section><section className="rounded-2xl border border-border bg-card p-5 sm:p-7"><SectionHeader eyebrow="الكلمة" title="آخر القراءات" />{data.readings?.length ? data.readings.slice(0, 5).map((reading) => <div key={reading.id} className="flex items-center gap-3 border-b border-border/70 py-4 last:border-0"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 text-primary"><BookOpen size={16} /></div><div className="flex-1"><div className="text-sm font-bold">{reading.book} {reading.chapter}</div><div className="mt-1 text-[10px] text-muted-foreground">{fmtDate(reading.date)}</div></div></div>) : <EmptyState icon={BookOpen} title="لا قراءات بعد" body="لم يسجل الطالب قراءات." />}</section></div></>;
}

function PageSkeleton() { return <div><div className="skeleton mb-8 h-28 max-w-xl rounded-2xl" /><div className="grid gap-6 lg:grid-cols-2"><div className="skeleton h-[420px] rounded-2xl" /><div className="skeleton h-[420px] rounded-2xl" /></div></div>; }

function Router() {
  return <ErrorBoundary><Switch>
    <Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/signup" component={Signup} />
    <Route path="/student/spiritual"><Protected><SpiritualPage /></Protected></Route>
    <Route path="/student/bible"><Protected><BiblePage /></Protected></Route>
    <Route path="/student/attendance"><Protected><AttendancePage /></Protected></Route>
    <Route path="/student/studies"><Protected><StudiesPage /></Protected></Route>
    <Route path="/servant/attendance"><Protected><ServantAttendancePage /></Protected></Route>
    <Route path="/servant/spiritual"><Protected><ServantSpiritualPage /></Protected></Route>
    <Route path="/servant/readings"><Protected><ServantReadingsPage /></Protected></Route>
    <Route path="/servant/studies"><Protected><ServantStudiesPage /></Protected></Route>
    <Route path="/servant/students/:id"><Protected><StudentProfilePage /></Protected></Route>
    <Route component={NotFound} />
  </Switch></ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter></QueryClientProvider>;
}

export default App;